NOTFOR = {'en': {'pldp': 'Not for anyone looking for motivation talks without practice — PLDP requires fieldwork, feedback and a capstone.', 'habits': 'Not for anyone wanting a quick fix in a weekend — one habit, four weeks, daily practice.', 'sales': 'Not for teams looking for pressure tactics or guaranteed figures — this is behaviour and systems, honestly taught.', 'teach': 'Not a lecture to sit through — teachers practise on their own classroom from week one.', 'homes': 'Not therapy and not counselling for serious crises — those are referred to qualified clinicians.', 'rise': 'Not for passive listeners — young people build and present their own one-year plan.'}, 'ur': {'pldp': 'یہ ان کے لیے نہیں جو مشق کے بغیر صرف ترغیبی گفتگو چاہتے ہوں — PLDP میں فیلڈ ورک، فیڈ بیک اور اختتامی منصوبہ لازم ہے۔', 'habits': 'یہ ان کے لیے نہیں جو ویک اینڈ میں فوری حل چاہتے ہوں — ایک عادت، چار ہفتے، روزانہ کی مشق۔', 'sales': 'یہ ان ٹیموں کے لیے نہیں جو دباؤ کی چالیں یا ضمانت شدہ اعداد چاہتی ہوں — یہ رویہ اور نظام ہے، دیانت داری سے سکھایا ہوا۔', 'teach': 'یہ بیٹھ کر سننے والا لیکچر نہیں — اساتذہ پہلے ہفتے سے اپنی ہی کلاس پر مشق کرتے ہیں۔', 'homes': 'یہ تھراپی نہیں اور نہ سنگین بحرانوں کی کونسلنگ — وہ مستند طبی ماہرین کی طرف ریفر کیے جاتے ہیں۔', 'rise': 'یہ غیر فعال سننے والوں کے لیے نہیں — نوجوان اپنا ایک سالہ منصوبہ خود بناتے اور پیش کرتے ہیں۔'}, 'ar': {'pldp': 'ليس لمن يبحث عن حديث تحفيزي دون ممارسة — يتطلب PLDP عملًا ميدانيًا وتغذية راجعة ومشروع تخرج.', 'habits': 'ليس لمن يريد حلًا سريعًا في عطلة نهاية أسبوع — عادة واحدة، أربعة أسابيع، ممارسة يومية.', 'sales': 'ليس للفرق التي تبحث عن أساليب ضغط أو أرقام مضمونة — هذا سلوك وأنظمة، يُدرَّس بأمانة.', 'teach': 'ليس محاضرة للجلوس والاستماع — يمارس المعلمون على صفوفهم من الأسبوع الأول.', 'homes': 'ليس علاجًا ولا إرشادًا للأزمات الخطيرة — تُحال تلك إلى مختصين سريريين مؤهلين.', 'rise': 'ليس للمستمعين السلبيين — يبني الشباب خطتهم لعام كامل ويعرضونها بأنفسهم.'}}
